// IS THE BUNDLE THE ONE THE SOURCE WOULD PRODUCE?
//
// Every browser walk in this repo serves `public/app.js`, which is generated by
// esbuild and gitignored. Each of them checked only that the file EXISTED. A
// walk run after editing `src/` and before `npm run build` therefore measured
// the PREVIOUS build — the app as it was, under a session's belief that it was
// testing the app as it is — and reported green.
//
// It is the stale-artefact shape the repo already gates elsewhere (the
// walkthrough photographs, the changelog triplet, the generated pre-commit
// hook). The walks were the one generated thing with no freshness check, and
// they are the most expensive to run and the most trusted when they pass.
//
// It was found by an assertion that happened to read a string the same session
// had just changed: the walk failed saying the sheet "still says Make it
// repeat". Nothing structural would have caught it — a new audit added to a
// stale bundle measures the old markup and passes.
//
// Cheap on purpose: one stat of the bundle against the newest mtime under
// `src/`. No hashing, no build invocation. A walk should say what is wrong, not
// silently repair it — repairing is how a check stops being able to fail.

import { existsSync, statSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

/** Newest mtime under a directory, recursively. */
function newestUnder(dir) {
  let newest = 0;
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, e.name);
    if (e.isDirectory()) newest = Math.max(newest, newestUnder(p));
    else newest = Math.max(newest, statSync(p).mtimeMs);
  }
  return newest;
}

/**
 * Exits non-zero if `public/app.js` is missing or older than the newest file
 * under `src/`. `who` names the caller so the message says which walk stopped.
 */
export function requireFreshBundle(root, who) {
  const bundle = join(root, 'public', 'app.js');
  if (!existsSync(bundle)) {
    console.error(`public/app.js is missing — run \`npm run build\` first (${who}).`);
    process.exit(1);
  }
  const src = join(root, 'src');
  if (!existsSync(src)) return;
  const built = statSync(bundle).mtimeMs;
  const newest = newestUnder(src);
  if (newest > built) {
    const mins = Math.round((newest - built) / 60000);
    console.error(
      `public/app.js is STALE — src/ has changed since it was built`
      + `${mins > 0 ? ` (by ${mins} minute${mins === 1 ? '' : 's'})` : ''}.`);
    console.error(`Run \`npm run build\` first, or ${who} will measure the previous app`);
    console.error('and pass — which is what it did before this check existed.');
    process.exit(1);
  }
}
